import pytest

def average(xs):
    if not xs:
        raise ValueError("empty")
    return sum(xs) / len(xs)

CASES = [([1], 1), ([1, 2, 3], 2), ([-1, 1], 0), ([10**18] * 2, 10**18)]
for xs, want in CASES:
    assert average(xs) == want
with pytest.raises(ValueError):
    average([])

